begin;
do $$
declare t uuid; t2 uuid; operator uuid:=gen_random_uuid(); s uuid; o uuid; o2 uuid; c uuid; r jsonb; n numeric; denied boolean;
begin
 insert into auth.users(id,email) values(operator,'synthetic-'||operator||'@example.invalid');
 insert into public.tenants(slug,display_name,status) values('audit-'||gen_random_uuid(),'Synthetic audit','TRIAL') returning id into t;
 insert into public.tenants(slug,display_name,status) values('audit-other-'||gen_random_uuid(),'Synthetic other','TRIAL') returning id into t2;
 insert into public.tenant_memberships(tenant_id,user_id,role,active) values(t,operator,'owner',true);
 insert into public.inventory(tenant_id,code,name,unit,qty,min_qty,inventory_group) values(t,'audit-stock','Synthetic stock','un',7,10,'Ingrediente') returning id into s;
 insert into public.orders(tenant_id,ticket_number,items,total,payment,status,origin) values(t,1,jsonb_build_array(jsonb_build_object('name','Synthetic product','price',10,'qty',1,'stockDeductions',jsonb_build_object('audit-stock',3))),10,'Dinheiro','pendente','online') returning id into o;
 denied:=false;begin perform public.manage_store_operation(t,'order_status',o,'{"status":"aceito"}');exception when others then if sqlerrm not like '%permissão%' then raise;end if;denied:=true;end;
 assert denied,'Unauthenticated access rejected';
 perform set_config('request.jwt.claim.sub',operator::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',operator,'role','authenticated')::text,true);
 denied:=false;begin perform public.manage_store_operation(t2,'order_status',o,'{"status":"aceito"}');exception when others then if sqlerrm not like '%permissão%' then raise;end if;denied:=true;end;
 assert denied,'Other tenant rejected';
 r:=public.manage_store_operation(t,'order_status',o,'{"status":"aceito"}');assert r->>'status'='aceito','Order status works';
 denied:=false;begin perform public.manage_store_operation(t,'order_status',o,'{"status":"aceito","total":0}');exception when others then if sqlerrm not like '%valores%' then raise;end if;denied:=true;end;
 assert denied,'Order totals cannot be overwritten';
 r:=public.manage_store_operation(t,'cancel_order',o,'{}');
 select qty into n from public.inventory where id=s;assert n=10,'Historical consumption restored';
 assert jsonb_array_length(r->'restoredItems')=1,'Restoration reported';
 r:=public.manage_store_operation(t,'cancel_order',o,'{}');
 select qty into n from public.inventory where id=s;assert n=10,'Repeated cancellation cannot restore twice';
 insert into public.orders(tenant_id,ticket_number,items,total,payment,status,origin) values(t,2,'[{"name":"Synthetic product","price":20,"qty":1,"stockDeductions":{}}]',20,'Pix','pedido aberto','balcao') returning id into o2;
 denied:=false;begin perform public.manage_store_operation(t,'close_register',null,'{"grossTotal":999,"ordersCount":1}');exception when others then if sqlerrm not like '%mudou%' then raise;end if;denied:=true;end;
 assert denied,'Changed register refuses stale confirmation';
 r:=public.manage_store_operation(t,'close_register',null,'{"grossTotal":20,"ordersCount":1,"discount":2,"netTotal":99999}');
 c:=(r->>'id')::uuid;assert (r->>'net_total')::numeric=18,'Server recomputes closure totals';
 assert (select closure_id from public.orders where id=o2)=c,'Order belongs to one closure';
 assert (r#>>'{by_payment,Pix}')::numeric=20,'Payment amounts calculated on server';
 denied:=false;begin perform public.manage_store_operation(t,'close_register',null,'{"grossTotal":20,"ordersCount":1}');exception when others then if sqlerrm not like '%sem pedidos%' then raise;end if;denied:=true;end;
 assert denied,'Same sales cannot close twice';
 denied:=false;begin perform public.manage_store_operation(t,'cancel_order',o2,'{}');exception when others then if sqlerrm not like '%fechamento%' then raise;end if;denied:=true;end;
 assert denied,'Closed financial history cannot be changed by cancellation';
 assert (select count(*) from public.operation_audit where tenant_id=t)=3,'Auditable operator events recorded';
 assert not has_function_privilege('anon','public.manage_store_operation(uuid,text,uuid,jsonb)','execute'),'Anonymous API cannot operate register';
end $$;
rollback;
select '12 operational, authorization, ledger and closure assertions passed; synthetic fixtures rolled back' as result;
